using Microsoft.AspNetCore.Authorization;using Microsoft.Extensions.DependencyInjection;
namespace UAF.API.Authorization;
public static class AuthorizationPolicyExtensions{
 public static IServiceCollection AddUafAuthorization(this IServiceCollection services){ArgumentNullException.ThrowIfNull(services);services.AddSingleton<IAuthorizationHandler,PermissionAuthorizationHandler>();services.AddAuthorization(o=>{foreach(var p in UafPermissions.All)Add(o,$"Permission:{p}",p);Add(o,AuthorizationPolicies.AdmissionsStaff,UafPermissions.AdmissionsReview);Add(o,AuthorizationPolicies.AdmissionsDecision,UafPermissions.AdmissionsDecide);o.AddPolicy(AuthorizationPolicies.ApplicantSelfService,p=>p.RequireAuthenticatedUser().RequireRole("Student"));Add(o,AuthorizationPolicies.AcademicStructureAdmin,UafPermissions.AcademicStructureManage);Add(o,AuthorizationPolicies.StudentManagement,UafPermissions.StudentsManage);Add(o,AuthorizationPolicies.AcademicCatalogManagement,UafPermissions.AcademicCatalogManage);Add(o,AuthorizationPolicies.CourseOfferingManagement,UafPermissions.CourseOfferingsManage);Add(o,AuthorizationPolicies.FinanceManagement,UafPermissions.FinanceManage);Add(o,AuthorizationPolicies.EmployeeManagement,UafPermissions.EmployeesManage);Add(o,AuthorizationPolicies.AttendanceManagement,UafPermissions.AttendanceManage);Add(o,AuthorizationPolicies.AttendancePolicyManagement,UafPermissions.AttendancePolicyManage);Add(o,AuthorizationPolicies.ExaminationManagement,UafPermissions.ExaminationsManage);Add(o,AuthorizationPolicies.ExaminationApproval,UafPermissions.ExaminationsApprove);Add(o,AuthorizationPolicies.GradingScaleManagement,UafPermissions.GradingScalesManage);Add(o,AuthorizationPolicies.CourseGradeManagement,UafPermissions.CourseGradesManage);o.AddPolicy(AuthorizationPolicies.StudentAcademicRecord,p=>p.RequireAuthenticatedUser().RequireRole("Student"));Add(o,AuthorizationPolicies.GradeAppealReview,UafPermissions.GradeAppealsReview);Add(o,AuthorizationPolicies.GradeRevisionRequestManagement,UafPermissions.GradeRevisionsManage);Add(o,AuthorizationPolicies.GradeRevisionApproval,UafPermissions.GradeRevisionsApprove);Add(o,AuthorizationPolicies.TranscriptIssuance,UafPermissions.TranscriptsIssue);Add(o,AuthorizationPolicies.TimetableManagement,UafPermissions.TimetableManage);Add(o,AuthorizationPolicies.WorkflowManagement,UafPermissions.WorkflowsManage);Add(o,AuthorizationPolicies.AuditTrailRead,UafPermissions.AuditTrailRead);Add(o,AuthorizationPolicies.AnalyticsRead,UafPermissions.AnalyticsRead);});return services;}
 private static void Add(AuthorizationOptions o,string name,string permission)=>o.AddPolicy(name,p=>p.RequireAuthenticatedUser().AddRequirements(new PermissionRequirement(permission)));
}
